#include<bits/stdc++.h>
#define int long long
using namespace std;
vector<int>v[111111];
int d[111111],f[111111];
signed main(){
	ios::sync_with_stdio(0);cin.tie(0);cout.tie(0);
	int n;
	cin>>n;
	for(int i=1;i<n;i++){
		int x,y;
		cin>>x>>y;
		v[x].push_back(y);
		v[y].push_back(x);
		d[x]++,d[y]++;
	}
	queue<int>q;
	int g=n;
	for(int i=1;i<=n;i++){
		if(d[i]<=1){
			g--;
			f[i]=1;
			d[i]=0;
			q.push(i);
		}
	}
	while(!q.empty()){
		if(g<=2){
			break;
		}
		int x=q.front();
		q.pop();
		for(int i=0;i<v[x].size();i++){
			d[v[x][i]]--;
			if(d[v[x][i]]==1){
				g--;
				f[v[x][i]]=1;
				q.push(v[x][i]);
			}
		}
	}
	for(int i=1;i<=n;i++){
		if(f[i]==0){
			cout<<i<<" ";
		}
	}
    return 0;
}
